78	@RestController
79	@CrossOrigin(exposedHeaders = "errors, content-type")
80	@RequestMapping("/api")
81	public class OwnerRestControllerV1 implements OwnersApi {
82	
83	    /**
84	     * A pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
85	     * and a dotted domain. Deliberately conservative so obviously malformed values (e.g. a bare
86	     * word with no {@code @}) are rejected while ordinary addresses are accepted.
87	     */
88	    private static final Pattern EMAIL_PATTERN =
89	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
90	
91	    /** Dedicated audit logger; carries owner lifecycle side-effects. */
92	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
93	
94	    /** Request header carrying the client-supplied idempotency key for creates. */
95	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
96	
97	    /**
98	     * Remembers the owner created for each already-seen {@code Idempotency-Key}, so a create that
99	     * repeats with the same key returns the originally created owner (200) instead of creating a
100	     * duplicate. Keyed by the raw header value; the mapped value is the created owner's id.
101	     */
102	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
103	
104	    private final ClinicService clinicService;
105	
106	    private final OwnerMapper ownerMapper;
107	
108	    private final PetMapper petMapper;
109	
110	    private final VisitMapper visitMapper;
111	
112	    public OwnerRestControllerV1(ClinicService clinicService,
113	                                 OwnerMapper ownerMapper,
114	                                 PetMapper petMapper,
115	                                 VisitMapper visitMapper) {
116	        this.clinicService = clinicService;
117	        this.ownerMapper = ownerMapper;
118	        this.petMapper = petMapper;
119	        this.visitMapper = visitMapper;
120	    }
