147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Override
149	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
150	        // Idempotent create: if this request repeats an already-seen 'Idempotency-Key', return the
151	        // owner created the first time (200) rather than creating a duplicate.
152	        String idempotencyKey = idempotencyKey();
153	        if (idempotencyKey != null) {
154	            Integer existingId = idempotentCreates.get(idempotencyKey);
155	            if (existingId != null) {
156	                Owner existing = this.clinicService.findOwnerById(existingId);
157	                if (existing != null) {
158	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
159	                }
160	            }
161	        }
162	        List<String> missingFields = new ArrayList<>();
163	        if (isBlank(ownerFieldsDto.getFirstName())) {
164	            missingFields.add("firstName");
165	        }
166	        if (isBlank(ownerFieldsDto.getLastName())) {
167	            missingFields.add("lastName");
168	        }
169	        // Normalize whichever address form was supplied and fold it into the DTO: the structured
170	        // 'addressLine1'/'addressLine2' win when a non-blank 'addressLine1' is present, otherwise the
171	        // flat 'address' is used. The composed value is stored back into 'address' so every reader of
172	        // the owner's address sees the effective (structured-or-flat) value.
173	        applyAddress(ownerFieldsDto);
174	        if (isBlank(ownerFieldsDto.getAddress())) {
175	            missingFields.add("address");
176	        }
177	        if (isBlank(ownerFieldsDto.getCity())) {
178	            missingFields.add("city");
179	        }
180	        if (isBlank(ownerFieldsDto.getTelephone())) {
181	            missingFields.add("telephone");
182	        }
183	        if (!missingFields.isEmpty()) {
184	            throw new MissingOwnerFieldsException(missingFields);
185	        }
186	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
187	        LocalDate suppliedRegistrationDate = ownerFieldsDto.getRegistrationDate();
188	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
189	            throw new FutureRegistrationDateException(
190	                "registrationDate must not be later than the server date");
191	        }
192	        LocalDate registrationDate = toBusinessDay(
193	            suppliedRegistrationDate != null
194	                ? suppliedRegistrationDate
195	                : LocalDate.now());
196	        long registeredOnDay = this.clinicService.findAllOwners().stream()
197	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
198	            .count();
199	        if (registeredOnDay >= 100) {
200	            throw new DailyRegistrationLimitException(
201	                "100 or more owners have already been registered today");
202	        }
203	        boolean bulkSignupWarning = registeredOnDay > 80;
204	        String city = ownerFieldsDto.getCity();
205	        long ownersInCity = this.clinicService.findAllOwners().stream()
206	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
207	            .count();
208	        if (ownersInCity >= 50) {
209	            throw new CityAtCapacityException(
210	                "the owner's city already contains 50 or more owners");
211	        }
212	        String telephone = toE164(ownerFieldsDto.getTelephone());
213	        ownerFieldsDto.setTelephone(telephone);
214	        String email = normalizeEmail(ownerFieldsDto.getEmail());
215	        ownerFieldsDto.setEmail(email);
216	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
217	        String postcode = ownerFieldsDto.getPostcode();
218	        // Deterministic household id: owners with the same normalized last name and postcode
219	        // share it automatically, regardless of creation order. It is no longer created by the
220	        // 'sharesHousehold' flag; that flag now only bypasses the duplicate block below.
221	        String householdId = householdId(lastName, postcode);
222	        // The household is keyed on (last name, postcode), so its existing members are the
223	        // existing owners with the same computed household id. Both the duplicate block and the
224	        // household size below key off this value.
225	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
226	            .filter(existing -> !existing.isDeleted())
227	            .filter(existing -> householdId.equals(
228	                householdId(normalizeHousehold(existing.getLastName()), existing.getPostcode())))
229	            .toList();
230	        // A second owner in an existing household is admitted as a household member; their
231	        // membership level is capped below (level-ceiling rule) rather than rejected.
232	        // Single, consolidated duplicate check: reject only when the new owner's whole
233	        // derived identity key (telephone|email|householdId) equals an existing owner's.
234	        String identityKey = IdentityKeyDeriver.identityKey(telephone, email, householdId);
235	        boolean identityInUse = this.clinicService.findAllOwners().stream()
236	            .filter(existing -> !existing.isDeleted())
237	            .anyMatch(existing -> identityKey.equals(IdentityKeyDeriver.identityKey(
238	                existing.getTelephone(), existing.getEmail(),
239	                householdId(normalizeHousehold(existing.getLastName()), existing.getPostcode()))));
240	        if (identityInUse) {
241	            throw new DuplicateIdentityException(
242	                "an owner with the same identity key already exists");
243	        }
244	        HttpHeaders headers = new HttpHeaders();
245	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
246	        owner.setRegistrationDate(registrationDate);
247	        owner.setCustomerCode(deduplicateCustomerCode(
248	            customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName())));
249	        owner.setHouseholdId(householdId);
250	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
251	        owner.setBulkSignupWarning(bulkSignupWarning);
252	        // Household size after this create: existing members plus the owner being created.
253	        owner.setHouseholdSize(householdMembers.size() + 1);
254	        // Level-ceiling: the new owner's membership level cannot exceed one above the current
255	        // maximum level among their existing household members. With no existing member no cap
256	        // applies. The (possibly capped) level is stored so it is returned on create and on read.
257	        int naturalLevel = MembershipPointsDeriver.membershipLevel(
258	            MembershipPointsDeriver.membershipPoints(owner));
259	        int cappedLevel = naturalLevel;
260	        if (!householdMembers.isEmpty()) {
261	            int maxMemberLevel = householdMembers.stream()
262	                .mapToInt(MembershipPointsDeriver::effectiveMembershipLevel)
263	                .max()
264	                .orElseThrow();
265	            cappedLevel = Math.min(naturalLevel, maxMemberLevel + 1);
266	        }
267	        owner.setMembershipLevel(cappedLevel);
268	        // A declared household member is not a suspected duplicate, and no other create path
269	        // reaches here for a same-household owner, so a created owner is never flagged.
270	        owner.setPossibleDuplicate(false);
271	        owner.setPossibleDuplicateOf(null);
272	        owner.setDeleted(false);
273	        this.clinicService.saveOwner(owner);
274	        if (idempotencyKey != null) {
275	            idempotentCreates.put(idempotencyKey, owner.getId());
276	        }
277	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
278	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} "
279	            + "membershipNumber={}",
280	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
281	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
282	        headers.setLocation(UriComponentsBuilder.newInstance()
283	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
284	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
285	    }
286	
287	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
288	    @Override
289	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
290	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
291	        if (currentOwner == null) {
292	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
293	        }
294	        applyAddress(ownerFieldsDto);
295	        currentOwner.setAddress(ownerFieldsDto.getAddress());
296	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
297	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
298	        currentOwner.setCity(ownerFieldsDto.getCity());
299	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
300	        currentOwner.setLastName(ownerFieldsDto.getLastName());
301	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
302	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
303	        this.clinicService.saveOwner(currentOwner);
304	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
305	    }
306	
307	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
308	    @Transactional
309	    @Override
310	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
311	        Owner owner = this.clinicService.findOwnerById(ownerId);
312	        if (owner == null) {
313	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
314	        }
315	        owner.setDeleted(true);
316	        this.clinicService.saveOwner(owner);
317	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
318	    }
