328	        Pet pet = petMapper.toPet(petFieldsDto);
329	        owner.setId(ownerId);
330	        pet.setOwner(owner);
331	        pet.getType().setName(null);
332	        this.clinicService.savePet(pet);
333	        PetDto petDto = petMapper.toPetDto(pet);
334	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
