341	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
342	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
343	        if (currentOwner != null) {
