371	
372	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
373	    @Override
374	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
375	        Owner owner = this.clinicService.findOwnerById(ownerId);
376	        if (owner != null) {
377	            Pet pet = owner.getPet(petId);
378	            if (pet != null) {
379	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
380	            }
381	        }
382	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
383	    }
384	
385	    private static boolean isBlank(String value) {
386	        return value == null || value.isBlank();
387	    }
388	
389	    /**
390	     * Returns the {@code Idempotency-Key} header of the current request, or {@code null} when the
391	     * header is absent, blank, or there is no bound request. Read from the request context so the
392	     * generated {@link OwnersApi#addOwner} signature is left untouched.
393	     */
394	    private static String idempotencyKey() {
395	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attrs)) {
396	            return null;
397	        }
398	        String key = attrs.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
399	        return isBlank(key) ? null : key;
400	    }
401	
402	    /**
403	     * The fixed public-holiday calendar. A registration date that lands on any of these dates is
404	     * rolled forward, just as a weekend is, to the next non-holiday business day.
405	     */
406	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
407	        LocalDate.of(2026, 1, 1),
408	        LocalDate.of(2026, 1, 26),
409	        LocalDate.of(2026, 4, 25),
410	        LocalDate.of(2026, 12, 25),
411	        LocalDate.of(2026, 12, 28));
412	
413	    /**
414	     * Rolls a registration date forward to the next business day: when it falls on a Saturday, a
415	     * Sunday or a listed public holiday it is advanced one day at a time until a non-holiday weekday
416	     * is reached; an unaffected weekday is returned unchanged. This is applied to the effective
417	     * registration date (whether supplied in the request or defaulted to the server date), so every
418	     * value derived from the registration date sees the adjusted business day.
419	     */
420	    private static LocalDate toBusinessDay(LocalDate date) {
421	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
422	                || date.getDayOfWeek() == DayOfWeek.SUNDAY
423	                || PUBLIC_HOLIDAYS.contains(date)) {
424	            date = date.plusDays(1);
425	        }
426	        return date;
427	    }
428	
429	    /**
430	     * Normalizes a last name for household-duplicate comparison: leading and trailing whitespace is
431	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
432	     * lower-cased so that last names are compared case-insensitively.
433	     */
434	    private static String normalizeHousehold(String value) {
435	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
436	    }
437	
438	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
439	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
440	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
441	
442	    /**
443	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
444	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
445	     * upper-cased, and common street-type abbreviations are expanded token-by-token
446	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
447	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
448	     * used for every address comparison (household-duplicate detection and the shared household id).
449	     */
450	    private static String normalizeAddress(String value) {
451	        if (value == null) {
452	            return "";
453	        }
454	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
455	        if (collapsed.isEmpty()) {
456	            return "";
457	        }
458	        String[] tokens = collapsed.split(" ");
459	        StringBuilder sb = new StringBuilder();
460	        for (int i = 0; i < tokens.length; i++) {
461	            if (i > 0) {
462	                sb.append(' ');
463	            }
464	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
465	        }
466	        return sb.toString();
467	    }
468	
469	    /**
470	     * Folds an owner's supplied address into its canonical stored form on the given DTO, preferring
471	     * the structured fields when present. When a non-blank {@code addressLine1} is supplied, it and an
472	     * optional {@code addressLine2} are normalized ({@link #normalizeAddress}) and kept as the
473	     * structured lines; the flat {@code address} is set to the composed value ({@code addressLine1},
474	     * plus a single space and {@code addressLine2} when the second line is present). Otherwise the
475	     * structured lines are cleared and the flat {@code address} is set to the normalized flat input.
476	     * The resulting {@code address} is the effective value every address reader sees, and is blank
477	     * only when neither an {@code addressLine1} nor a flat {@code address} was supplied.
478	     */
479	    private static void applyAddress(OwnerFieldsDto ownerFieldsDto) {
480	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
481	        String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
482	        if (!isBlank(line1)) {
483	            ownerFieldsDto.setAddressLine1(line1);
484	            ownerFieldsDto.setAddressLine2(isBlank(line2) ? null : line2);
485	            ownerFieldsDto.setAddress(isBlank(line2) ? line1 : line1 + " " + line2);
486	        } else {
487	            ownerFieldsDto.setAddressLine1(null);
488	            ownerFieldsDto.setAddressLine2(null);
489	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
490	        }
491	    }
492	
493	    /**
494	     * Derives the stable {@code householdId} shared by all owners in a household: the first 12
495	     * hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. It is a pure,
496	     * deterministic function of the normalized last name and postcode, so every owner that shares
497	     * those values maps to the same identifier regardless of creation order. A {@code null}
498	     * postcode contributes the empty string.
499	     */
500	    private static String householdId(String normalizedLastName, String postcode) {
501	        String key = normalizedLastName + "|" + (postcode == null ? "" : postcode);
502	        return sha256Hex12(key);
503	    }
504	
505	    /** The first 12 lower-case hex characters (6 bytes) of the SHA-256 digest of {@code s}. */
506	    private static String sha256Hex12(String s) {
507	        try {
508	            byte[] digest = MessageDigest.getInstance("SHA-256")
509	                .digest(s.getBytes(StandardCharsets.UTF_8));
510	            StringBuilder sb = new StringBuilder(12);
511	            for (int i = 0; i < 6; i++) {
512	                sb.append(String.format("%02x", digest[i]));
513	            }
514	            return sb.toString();
515	        }
516	        catch (NoSuchAlgorithmException e) {
517	            throw new IllegalStateException("SHA-256 not available", e);
518	        }
519	    }
520	
521	    /**
522	     * Builds the {@code customerCode} assigned to a new owner, formatted
523	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the region code derived from the owner's postcode
524	     * ({@code NSW}/{@code VIC}/{@code QLD}, or {@code UNKNOWN}), and {@code HASH8} is the first 8
525	     * upper-case hex characters of SHA-256 over the owner's normalized E.164 telephone concatenated
526	     * with the last name (e.g. {@code 'NSW-1A2B3C4D'}). No sequence number is used, so the code is a
527	     * pure function of the owner's own identity fields.
528	     */
529	    private static String customerCode(String postcode, String telephone, String lastName) {
530	        String region = LocalityDeriver.region(postcode);
531	        String hash8 = sha256Hex8((telephone == null ? "" : telephone)
532	            + (lastName == null ? "" : lastName));
533	        return region + "-" + hash8;
534	    }
535	
536	    /**
537	     * De-duplicates a computed {@code customerCode} against the codes already assigned to existing
538	     * owners. If {@code base} is not currently in use it is returned unchanged; otherwise
539	     * {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that yields a code no
540	     * existing owner holds (e.g. a second collision on {@code 'NSW-1A2B3C4D'} becomes
541	     * {@code 'NSW-1A2B3C4D-2'}, a third {@code 'NSW-1A2B3C4D-3'}, and so on).
542	     */
543	    private String deduplicateCustomerCode(String base) {
544	        Set<String> existing = this.clinicService.findAllOwners().stream()
545	            .map(Owner::getCustomerCode)
546	            .filter(code -> code != null)
547	            .collect(Collectors.toSet());
548	        if (!existing.contains(base)) {
549	            return base;
550	        }
551	        int n = 2;
552	        while (existing.contains(base + "-" + n)) {
553	            n++;
554	        }
555	        return base + "-" + n;
556	    }
557	
558	    /** The first 8 upper-case hex characters (4 bytes) of the SHA-256 digest of {@code s}. */
559	    private static String sha256Hex8(String s) {
560	        try {
561	            byte[] digest = MessageDigest.getInstance("SHA-256")
562	                .digest(s.getBytes(StandardCharsets.UTF_8));
563	            StringBuilder sb = new StringBuilder(8);
564	            for (int i = 0; i < 4; i++) {
565	                sb.append(String.format("%02X", digest[i]));
566	            }
567	            return sb.toString();
568	        }
569	        catch (NoSuchAlgorithmException e) {
570	            throw new IllegalStateException("SHA-256 not available", e);
571	        }
572	    }
573	
574	    /**
575	     * Counts the existing owners that share the given first name and last name, compared
576	     * case-insensitively. This is evaluated over the owners that already exist (i.e. before the
577	     * owner currently being created is saved), so it reflects how many namesakes preceded the
578	     * new owner.
579	     */
580	    private int countNamesakes(String firstName, String lastName) {
581	        return (int) this.clinicService.findAllOwners().stream()
582	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
583	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
584	            .count();
585	    }
586	
587	    /**
588	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
589	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
590	     * national one, a single leading {@code '0'} is dropped, and the default country code
591	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'}, and its
592	     * national number must have the length required by its country code ({@code '+61'} requires 9
593	     * national digits, {@code '+1'} requires 10); otherwise an {@link InvalidTelephoneException} is
594	     * raised (reported to the client as 400).
595	     */
596	    private static String toE164(String telephone) {
597	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
598	        String digits;
599	        if (cleaned.startsWith("+")) {
600	            digits = cleaned.substring(1);
601	        } else {
602	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
603	            digits = "61" + national;
604	        }
605	        if (!digits.matches("[0-9]{8,15}")) {
606	            throw new InvalidTelephoneException(
607	                "telephone must form a valid E.164 number with 8 to 15 digits");
608	        }
609	        validateNationalLength(digits);
610	        return "+" + digits;
611	    }
612	
613	    /** National-number length required for each supported country code (digits after the code). */
614	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY_CODE = Map.of(
615	        "61", 9, "1", 10);
616	
617	    /**
618	     * Validates the national-number length of an E.164 number (digits after the {@code '+'}) against
619	     * its country code. {@code '+61'} requires 9 national digits and {@code '+1'} requires 10; a
620	     * mismatch raises an {@link InvalidTelephoneException} (reported to the client as 400). Country
621	     * codes without a configured requirement are left to the general 8-to-15-digit rule.
622	     */
623	    private static void validateNationalLength(String digits) {
624	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY_CODE.entrySet()) {
625	            String code = entry.getKey();
626	            if (digits.startsWith(code)) {
627	                int nationalLength = digits.length() - code.length();
628	                if (nationalLength != entry.getValue()) {
629	                    throw new InvalidTelephoneException(
630	                        "telephone national number must have " + entry.getValue()
631	                            + " digits for country code +" + code);
632	                }
633	                return;
634	            }
635	        }
636	    }
637	
638	    /**
639	     * Inclusive 4-digit postcode range fixed for each region: NSW 2000-2099, VIC 3000-3099,
640	     * QLD 4000-4099. A region absent from this table (i.e. a city with no known region) accepts
641	     * any 4-digit postcode.
642	     */
643	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
644	        "NSW", new int[] {2000, 2099},
645	        "VIC", new int[] {3000, 3099},
646	        "QLD", new int[] {4000, 4099});
647	
648	    /**
649	     * Validates an owner's optional {@code postcode}. When absent (or blank) it is left unvalidated
650	     * and the owner is accepted, keeping the request contract backward-compatible. When present it
651	     * must be a 4-digit value; and when the owner's city maps to a known region it must fall within
652	     * that region's fixed inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with
653	     * no known region accepts any 4-digit postcode. A violation raises an
654	     * {@link InvalidPostcodeException} (reported to the client as 400).
655	     */
656	    private static void validatePostcode(String city, String postcode) {
657	        if (isBlank(postcode)) {
658	            return;
659	        }
660	        if (!postcode.matches("[0-9]{4}")) {
661	            throw new InvalidPostcodeException("postcode must be a 4-digit value");
662	        }
663	        int[] range = REGION_POSTCODE_RANGE.get(LocalityDeriver.localityForCity(city));
664	        if (range == null) {
665	            return;
666	        }
667	        int value = Integer.parseInt(postcode);
668	        if (value < range[0] || value > range[1]) {
669	            throw new InvalidPostcodeException(
670	                "postcode is out of range for the owner's city region");
671	        }
672	    }
673	
674	    /**
675	     * Disposable email domains that are rejected outright: an owner whose email domain is one of
676	     * these is refused with a 400. Compared case-insensitively (the email is lower-cased before the
677	     * check).
678	     */
679	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
680	        "mailinator.com", "tempmail.com", "guerrillamail.com");
681	
682	    /**
683	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
684	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
685	     * is raised (reported to the client as 400). Its domain must not be on the disposable-domain
686	     * blocklist ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}), otherwise
687	     * an {@link InvalidEmailException} is likewise raised (400). A valid value is returned lower-cased
688	     * so it is stored and returned in canonical form.
689	     */
690	    private static String normalizeEmail(String email) {
691	        if (isBlank(email)) {
692	            return null;
693	        }
694	        String trimmed = email.trim();
695	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
696	            throw new InvalidEmailException("email must be a syntactically valid address");
697	        }
698	        String normalized = trimmed.toLowerCase(Locale.ROOT);
699	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
700	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
701	            throw new InvalidEmailException("email domain is on the disposable-domain blocklist");
702	        }
703	        return normalized;
704	    }
705	}
